def brief(d):
    out={}
    for k,v in d.items():
        if k=='changed_cell_count': out[k]=v
        else:
            out[k]=[ {kk:vv for kk,vv in e.items() if kk in ('at','from','to','pixels','before_color','after_color','bbox','color')} for e in v]
    return out

retained_functions.tip:
def tip():
    seg = current_frame.segmentation
    out=[]
    for n in seg['nodes']:
        if n['color'] in ('b','S') and n['pixels']<=16 and n['boundary'][0][0]<30:
            b=n['boundary']
            out.append((n['color'], min(p[0] for p in b), min(p[1] for p in b), max(p[0] for p in b), max(p[1] for p in b)))
    return out

